window.kbPageData["views/practice/s-4fdadcb77809c673"] = {"key":"practice/s-4fdadcb77809c673","state":{"route":"practice/s-4fdadcb77809c673"},"tree":"<a data-toc-link href=\"#skills/shenlun\">申论技能首页</a><details data-branch=\"module-归纳概括\"><summary>归纳概括</summary><div class=\"tocChildren\"><a data-toc-link href=\"#practice/s-c898afc5816920c2\">概括作用与成效</a><a data-toc-link href=\"#practice/s-0b47c7faa1dcfbc7\">提炼做法与经验</a><a data-toc-link href=\"#practice/s-75a1eb1e46268fd8\">归类概括材料中的问题</a><a data-toc-link href=\"#practice/s-4863baf2b4febcf4\">配对概括做法与成效</a><a data-toc-link href=\"#practice/s-c94c813ed743298a\">从材料提取概念特征</a><a data-toc-link href=\"#practice/s-4da331cba0998f2b\">分条梳理不同立场与分歧</a></div></details><details data-branch=\"module-综合分析\"><summary>综合分析</summary><div class=\"tocChildren\"><a data-toc-link href=\"#practice/s-43e39afd29a17e74\">解释含义与作用</a><a data-toc-link href=\"#practice/s-599008555ed60dda\">分析现象形成的原因</a><a data-toc-link href=\"#practice/s-93367fee5c934df6\">从案例推导改进建议</a></div></details><details data-branch=\"module-提出对策\"><summary>提出对策</summary><div class=\"tocChildren\"><a data-toc-link href=\"#practice/s-c6bd983baf5dd3ae\">根据问题成因逐项提出措施</a><a data-toc-link href=\"#practice/s-ecba3f8c2c1d3b9b\">将外地经验转化为本地措施</a><a data-toc-link href=\"#practice/s-9b570af6b9f113ee\">按治理环节组织对策</a><a data-toc-link href=\"#practice/s-91888cb77ec12615\">从材料反馈中提炼改进建议</a></div></details><details data-branch=\"module-应用文写作\"><summary>应用文写作</summary><div class=\"tocChildren\"><a data-toc-link href=\"#practice/s-171ebed39b4fe1cf\">汇报与交流发言</a><a data-toc-link href=\"#practice/s-b92b682e65d12042\">面向公众动员参与</a><a data-toc-link href=\"#practice/s-cabc6af5d656b214\">宣传介绍与活动报道</a><a data-toc-link href=\"#practice/s-5cd530a611f08110\">编写案例摘要</a><a data-toc-link href=\"#practice/s-9f175b7eb1a79028\">陈述事由与请求</a><a data-toc-link href=\"#practice/s-38dece0b54a49be3\">拟定工作事项与措施</a><a data-toc-link href=\"#practice/s-c8dfde3ede3eadab\">撰写案例短评或点评</a></div></details><details data-branch=\"module-文章写作\" open><summary>文章写作</summary><div class=\"tocChildren\"><a data-toc-link href=\"#practice/s-b8139af04b609dce\">展开分论点的论证</a><a data-toc-link href=\"#practice/s-4fdadcb77809c673\" aria-current=\"page\">围绕中心论点组织分论点</a><a data-toc-link href=\"#practice/s-ab43045e4cab9ffe\">从材料立意并确立中心论点</a></div></details>","packs":{"国考 2023 地市级 申论#5":"ef1df253778501c3d11defc7","国考 2024 副省级 申论#5":"ef1df253778501c3d11defc7","国考 2024 行政执法 申论#5":"ef1df253778501c3d11defc7","国考 2025 副省级 申论#5":"78a6d0ac301d3980dc17816d","国考 2025 地市级 申论#5":"78a6d0ac301d3980dc17816d","国考 2025 行政执法 申论#5":"78a6d0ac301d3980dc17816d","江苏 2024 A类 申论#4":"4a5f71bdeaa34cd81995cba3","江苏 2025 A类 申论#4":"4a5f71bdeaa34cd81995cba3"},"questions":{"国考 2023 地市级 申论#5":{"paper":"国考 2023 地市级 申论","n":5,"mod":"申论","src":["ac29447768aa30db2247.pdf",4],"asrc":["88c33effee950c9e9e6a.pdf",3]},"国考 2024 副省级 申论#5":{"paper":"国考 2024 副省级 申论","n":5,"mod":"申论","src":["22a70a7d604f43d79958.pdf",4],"asrc":["e63c52d7634f0ab7a98f.pdf",4]},"国考 2024 行政执法 申论#5":{"paper":"国考 2024 行政执法 申论","n":5,"mod":"申论","src":["b9a9a500aad1608fddd0.pdf",4],"asrc":["b899d5c3aecda01e69ec.pdf",4]},"国考 2025 副省级 申论#5":{"paper":"国考 2025 副省级 申论","n":5,"mod":"申论","src":["7543a550935cd0cc16be.pdf",4],"asrc":["3f81b5d39fbc5b1d205d.pdf",3]},"国考 2025 地市级 申论#5":{"paper":"国考 2025 地市级 申论","n":5,"mod":"申论","src":["16fbc0b81d8aafc9f70b.pdf",4],"asrc":["cfcf70b08272c4dfe4c2.pdf",4]},"国考 2025 行政执法 申论#5":{"paper":"国考 2025 行政执法 申论","n":5,"mod":"申论","src":["dbb2469ea58338709f40.pdf",4],"asrc":["d1fc3fe21ef6ae3b1ae6.pdf",3]},"江苏 2024 A类 申论#4":{"paper":"江苏 2024 A类 申论","n":4,"mod":"申论","src":["4fbf1d8260d6665235b0.pdf",4],"asrc":["411b0576fd3fd921b344.pdf",2]},"江苏 2025 A类 申论#4":{"paper":"江苏 2025 A类 申论","n":4,"mod":"申论","src":["b1f59532fef09ba66d75.pdf",4],"asrc":["c5e59296c6aaf5bdf3eb.pdf",2]}},"first":{"qs":{"国考 2023 地市级 申论#5":{"paper":"国考 2023 地市级 申论","n":5,"mod":"申论","src":["ac29447768aa30db2247.pdf",4],"asrc":["88c33effee950c9e9e6a.pdf",3],"m":["d8aed48987730819","83b1ed6111d1ae4e","dd9e2108e0e953e8","d4e0e7e85f06007d","01efb1670d7870db"],"task":"围绕材料5提出的追寻长期价值，自选角度、自拟题目，参考给定资料并联系实际，写一篇1000—1200字的文章。","current_affairs":{"state":"否","event":null,"year":null,"basis":"材料5提供了写作所需的核心观点，历史与现实事例可自行选取，作答无须掌握窗口内的特定事件或政策部署。"},"links":[{"id":"k-8aa6c40ec20de676","label":"面对不确定性，持续投入能产生长期价值的事务有助于增强适应韧性","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"M1","quote":"增强适应持续变化的环境的能力","why":"材料将增强适应能力与承受短期挫折、抵御短期诱惑和坚持长期投入相联系。","origin":"逐题标记"},{"id":"k-4d3454f7f078b01c","label":"个人建立理性认知框架有助于抵御短期干扰并坚持长期目标","catalog_id":null,"type":"观点与论证","role":"解题依据","field":"M1","quote":"建立理性的认知框架，不受繁杂噪声的影响","why":"材料指出个人需要保持判断力，参考文章将其落实为自主确定发展方向和持续学习实践。","origin":"逐题标记"},{"id":"k-d814f6a0f46ef3a6","label":"企业通过持续创新和改进经营创造长期价值","catalog_id":null,"type":"观点与论证","role":"解题依据","field":"M1","quote":"要求企业不断进化、不断创造价值","why":"材料强调企业要持续创造价值，参考文章从技术研发和经营改进两方面阐明实现路径。","origin":"逐题标记"},{"id":"k-475b76e8b7a3951f","label":"政府以长远公共利益为导向持续推进发展目标","catalog_id":null,"type":"观点与论证","role":"解题依据","field":"answer","quote":"党和政府投入四十余年的努力将长期构想转化","why":"参考文章以建设小康社会为例，说明政府需要持续投入才能实现长远公共目标。","origin":"逐题标记"},{"id":"k-4ac3bc37c7df3b81","label":"社会力量持续投入支撑人类长远发展的领域可形成正向循环","catalog_id":null,"type":"观点与论证","role":"解题依据","field":"M1","quote":"无数力量汇聚到支撑人类长期发展的领域","why":"材料提出汇聚社会力量有利于持续发展，参考文章以文化事业和文明传承阐明这一判断。","origin":"逐题标记"},{"id":"s-4fdadcb77809c673","label":"从材料观点提炼中心论点并按主体组织分论点","catalog_id":null,"type":null,"role":"直接考查","field":"answer","quote":"分别从个\n人、企业、政府、社会的角度写到了追求长期价值的对策","why":"参考文章围绕长期价值确立中心论点，再按不同主体的责任和行动展开论证。","origin":"逐题标记"},{"id":"s-b8139af04b609dce","label":"用现实事例论证分论点","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"参考给定资料，联系实际","why":"题目要求把材料观点与实际相联系，参考文章用小康社会建设说明持续推进长远目标的作用。","origin":"逐题标记","originalId":"s-8442770ed788450c"}],"stem":"请你深入思考“给定资料5”中这位学者文章的有关内容，参考给定资料，联系实际，自选角度，自拟题目，写一篇\n文章。（35分）\n要求：\n（1）观点明确，见解深刻；\n（2）参考给定资料，但不拘泥于给定资料；\n（3）思路清晰，语言流畅；\n（4）字数1000-1200字。","options":[],"answer":"","analysis":"做长期主义的践行者\n  从席卷全球的数次金融危机到经济一体化、从两极格局的崩溃到多极化格局的建立、从“温室效应”不断加剧到新\n冠疫情肆虐……频发的“黑天鹅”提示我们，人类社会的不确定性越来越强。我们注定无法逃避，必须增强应对的韧性\n和能力，不惧短期挫折，抵御短期诱惑，心怀信念，坚持把时间和精力投入到能够产生长期价值的事上。\n  追求长期价值，个人要保持清醒，建立起理性的认知框架。不仅要以社会需求，个人的理想、志向等为出发\n点，树立发展方向和目标；更要脚踏实地，在目标领域坚持深耕，终身学习，追求自我能力的综合性提升。长远目\n标的确定，不是跟风，不是人云亦云，而是应该在自身优势、兴趣喜好的基础上，根据社会发展趋势，找到适合自\n\n我的发展方向。但仅有目标是远远不够的，还要不断实践尝试、努力奋斗，要树立终身学习的理念，跟自身专业领\n域的资深人士学习，积累经验，还要紧跟时代变化，了解社会上的新知识、新思维、新观念，多创新、多尝试、多\n改进，不断提升自我综合能力。\n  追求长期价值，企业要树立长远发展格局，要求企业要不断进化、创造价值。既要坚持探索创新，掌握核心技\n术，还要持续优化经营管理和商业发展模式，推动产品和服务升级，进而创造经济效益和社会价值，承担社会责\n任。各个行业的领军企业，都深知技术的重要性，加大自主研发投入，获取独立知识产权，掌握行业话语权。企业\n自身的能力过硬是立身的基础，但也要有好的经营发展模式。在企业经营过程中，要不断优化组织架构，还要将中\n国文化精髓融入西方管理学中，打造中国特色先进管理体系，更要立足市场，根据市场需求，调整经营模式和发展\n方向，为社会经济增长、缓解就业压力等贡献力量。\n  追求长期价值，政府要树立担当意识，立足长期利益，致力长远发展。要根据群众内部矛盾的变化，改善民生\n福祉，不断满足人民群众日益增长的美好生活需要；还要坚定不移捍卫国家利益，讲好“中国故事”，提升中华文化的\n国际影响力。邓小平同志在四十多年前提出了建设小康社会的目标，党和政府投入四十余年的努力将长期构想转化\n为现实；步入发展新时期，我们又树立了社会主义全面现代化的目标愿景，这需要政府坚持践行创新、协调、绿\n色、开放、共享的理念，为建设美好生活持续奋斗。此外，面对风云诡谲的国际环境，我国政府也必须维护国家利\n益，坚决抵制霸权主义，还要在国际舞台上传播“仁义礼智信”“以和为贵”等优秀传统文化，提升文化软实力。\n  社会发展的长期价值从根本上而言是人类文明的传承和延续、智慧的传播与发展，因此要从知识、道德、艺\n术、教育等方面，推动人类文化事业的建设和文明的延续与进步。在时间的淘洗下，有形的物质终会湮灭，一直传\n承并更新的是思想的、精神的“结晶”。然而，社会文明的发展是需要维护、需要注入的，纵观人类发展的长河，多少\n曾经璀璨繁荣的文明最后也走向了衰落乃至消亡。这启示我们，要在文化事业上倾斜更多资源，切实全面提高全民\n族的思想道德素质和科学文化素质，才能让社会永续发展。\n  在长期主义的路上，我们与时间成为朋友，与同伴并行，我们不断调整、不断提升、不断成长，终有一日，云\n海荡朝日，春色任天涯。\n文章分析\n                      做长期主义的践行者\n  【标题的优点：首先，范文的标题“做长期主义的践行者”突出了“长期价值”这一主题。其次，形式上，文字简洁\n明快，不拖沓。】\n  （1）从席卷全球的数次金融危机到经济一体化、从两极格局的崩溃到多极化格局的建立、从“温室效应”不断加\n剧到新冠疫情肆虐……频发的“黑天鹅”提示我们，人类社会的不确定性越来越强。（2）我们注定无法逃避，必须增\n强应对的韧性和能力，不惧短期挫折，抵御短期诱惑，心怀信念，坚持把时间和精力投入到能够产生长期价值的事\n上。\n  【开头的优点：★内容方面。范文的开头是紧扣“长期价值”这一主题展开的。首先，开头点出主题，做到了主题\n明确。其次，对“长期价值”这一主题进行了分析阐述，指出了（1）追求长期价值的时代背景；（2）追求长期价值的\n对策。★文字表达方面：使用了排比的修辞手法，使文字表达更加有力。】\n  追求长期价值，个人要保持清醒，建立起理性的认知框架。（1）不仅要以社会需求，个人的理想、志向等为出\n发点，树立发展方向和目标；更要脚踏实地，在目标领域坚持深耕，终身学习，追求自我能力的综合性提升。（2）\n长远目标的确定，不是跟风，不是人云亦云，而是应该在自身优势、兴趣喜好的基础上，根据社会发展趋势，找到\n适合自我的发展方向。（3）但仅有目标是远远不够的，还要不断实践尝试、努力奋斗，要树立终身学习的理念，跟\n自身专业领域的资深人士学习，积累经验，还要紧跟时代变化，了解社会上的新知识、新思维、新观念，多创新、\n多尝试、多改进，不断提升自我综合能力。\n  【论述段1的优点：★观点句：范文的观点句是紧扣“长期价值”这一文章主题提出的。形式上，它在段首处直接\n写出，位置突出，容易发现。内容上，关键词突出，内容要点明确，可以明显看出它是从“建立理性的认知框架”这个\n角度入手，指出了个人追求长期价值的对策。★论述内容：（1）先总体介绍了“树立发展方向，脚踏实地奋斗”；\n（2）接着介绍了“找到适合自我的发展方向”；（3）最后介绍了“不断实践尝试、努力奋斗”。注意：以上三个方面的\n内容都是紧扣“追求长期价值，个人要保持清醒，建立起理性的认知框架”这个观点句进行分析论述的，论述的针对性\n强，内容层次丰富。最后，在论述方法上主要采用了讲道理的方式，论述清晰有力。】\n  追求长期价值，企业要树立长远发展格局，要求企业要不断进化、创造价值。（1）既要坚持探索创新，掌握核\n心技术，还要持续优化经营管理和商业发展模式，推动产品和服务升级，进而创造经济效益和社会价值，承担社会\n责任。（2）各个行业的领军企业，都深知技术的重要性，加大自主研发投入，获取独立知识产权，掌握行业话语\n权。（3）企业自身的能力过硬是立身的基础，但也要有好的经营发展模式。在企业经营过程中，要不断优化组织架\n构，还要将中国文化精髓融入西方管理学中，打造中国特色先进管理体系，更要立足市场，根据市场需求，调整经\n营模式和发展方向，为社会经济增长、缓解就业压力等贡献力量。\n  【论述段2的优点：★观点句：范文的观点句是紧扣“长期价值”这一文章主题提出的。形式上，它在段首处直接\n写出，位置突出，容易发现。内容上，关键词突出，内容要点明确，可以明显看出它是从“树立长远发展格局”这个角\n\n度入手，指出了企业追求长期价值的对策。★论述内容：（1）先总体介绍了“掌握核心技术，优化企业管理”；（2）\n接着介绍了“加大研发投入，获取知识产权”；（3）最后介绍了“优化组织架构，打造先进管理体系”。注意：以上三个\n方面的内容都是紧扣“追求长期价值，企业要树立长远发展格局，要求企业要不断进化、创造价值”这个观点句进行分\n析论述的，论述的针对性强，内容层次丰富。最后，在论述方法上主要采用了讲道理的方式，论述深刻有力。】\n  追求长期价值，政府要树立担当意识，立足长期利益，致力长远发展。（1）要根据群众内部矛盾的变化，改善\n民生福祉，不断满足人民群众日益增长的美好生活需要；还要坚定不移捍卫国家利益，讲好“中国故事”，提升中华文\n化的国际影响力。（2）邓小平同志在四十多年前提出了建设小康社会的目标，党和政府投入四十余年的努力将长期\n构想转化为现实；步入发展新时期，我们又树立了社会主义全面现代化的目标愿景，这需要政府坚持践行创新、协\n调、绿色、开放、共享的理念，为建设美好生活持续奋斗。此外，（3）面对风云诡谲的国际环境，我国政府也必须\n维护国家利益，坚决抵制霸权主义，还要在国际舞台上传播“仁义礼智信”“以和为贵”等优秀传统文化，提升文化软实\n力。\n  【论述段3的优点：★观点句：范文的观点句是紧扣“长期价值”这一文章主题提出的。形式上，它在段首处直接\n写出，位置突出，容易发现。内容上，关键词突出，内容要点明确，可以明显看出它是从“树立担当意识”这个角度入\n手，指出了政府追求长期价值的对策。★论述内容：（1）先总体介绍了“改善民生福祉，捍卫国家利益”；（2）接着\n介绍了“践行新发展理念，建设美好生活”；（3）最后介绍了“维护国家利益，提升文化软实力”。注意：以上三个方面\n的内容都是紧扣“追求长期价值，政府要树立担当意识，立足长期利益，致力长远发展”这个观点句进行分析论述的，\n论述的针对性强，内容层次丰富。最后，在论述方法上将讲道理和举例子相结合，做到了丰富多样。】\n  社会发展的长期价值从根本上而言是人类文明的传承和延续、智慧的传播与发展，因此要从知识、道德、艺\n术、教育等方面，推动人类文化事业的建设和文明的延续与进步。（1）在时间的淘洗下，有形的物质终会湮灭，一\n直传承并更新的是思想的、精神的“结晶”。然而，社会文明的发展是需要维护、需要注入的，纵观人类发展的长河，\n多少曾经璀璨繁荣的文明最后也走向了衰落乃至消亡。这启示我们，（2）要在文化事业上倾斜更多资源，切实全面\n提高全民族的思想道德素质和科学文化素质，才能让社会永续发展。\n  【论述段4的优点：★观点句：范文的观点句是紧扣“长期价值”这一文章主题提出的。形式上，它在段首处直接\n写出，位置突出，容易发现。内容上，关键词突出，内容要点明确，可以明显看出它是从“传承延续人类文明”这个角\n度入手，指出了社会追求长期价值的对策。★论述内容：（1）先介绍了“社会文明发展的规律”；（2）再介绍了“传\n承社会文明的对策”。注意：以上两个方面的内容都是紧扣“社会发展的长期价值从根本上而言是人类文明的传承和延\n续、智慧的传播与发展，因此要从知识、道德、艺术、教育等方面，推动人类文化事业的建设和文明的延续与进\n步”这个观点句进行分析论述的，论述的针对性强，内容层次丰富。最后，在论述方法主要采用了讲道理的方式，论\n述简洁有力。】\n  【论述段之间的关系：★内容的内在逻辑：范文的论述段之间是依照递进的逻辑展开的。论述段1-4分别从个\n人、企业、政府、社会的角度写到了追求长期价值的对策，由小到大、从微观到宏观，对文章主题的论述层层深\n入。】\n  在长期主义的路上，我们与时间成为朋友，与同伴并行，我们不断调整、不断提升、不断成长，终有一日，云\n海荡朝日，春色任天涯。\n  【结尾的优点：范文的结尾回扣了“长期价值”这个主题，并发出了展望。】","figs":[],"state":"已标记","notes":[],"domains":["社会治理","公共管理","经济"],"nature":"综合题","current":false},"国考 2024 副省级 申论#5":{"paper":"国考 2024 副省级 申论","n":5,"mod":"申论","src":["22a70a7d604f43d79958.pdf",4],"asrc":["e63c52d7634f0ab7a98f.pdf",4],"m":["178887103fc17b90","65cf3240786dbd61","fb5ef365f00b5993","d2f9c6b742757876","6644520b217e1626"],"task":"参考给定材料并联系实际，自选角度、自拟题目，写一篇1000～1200字的文章，论述如何发掘旧事物的价值并使其重焕生机。","current_affairs":{"state":"否","event":null,"year":null,"basis":"题目可依据旧物回收、修复和利用案例展开论证，无须掌握窗口内的具体事件或政策部署。"},"links":[{"id":"k-b7c045465e9e618c","label":"旧物的技艺、记忆、审美与再利用价值","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"要充分挖掘旧物中承载的技艺、情感和故事，重新认识其蕴含的审美和文化基因，并赋予其经济价值。","why":"这些可发掘的价值说明了旧物在原有用途减弱后仍值得保存和利用的理由。","origin":"逐题标记"},{"id":"k-a2892e57edb4b096","label":"旧物保护修复需要专业技法与耐心投入","catalog_id":null,"type":"观点与论证","role":"解题依据","field":"answer","quote":"这既需要专业的技巧，也要有情感的投入。","why":"专业修复有助于避免不可逆的损伤，情感投入有助于支撑细致而耗时的修复工作。","origin":"逐题标记"},{"id":"k-e0770253109af00a","label":"融入当代日常生活有助于旧物长期存续","catalog_id":null,"type":"观点与论证","role":"解题依据","field":"M1","quote":"老物件最好的存续方式就是进入人们的日常生活之\n中。","why":"旧物与当代家居结合，使人们能够在日常使用中重新体验传统技艺与审美。","origin":"逐题标记"},{"id":"s-4fdadcb77809c673","label":"把材料中的主题判断转化为有实例支撑的分论点","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"入思考，参考给定材料，联系实际，自选角度，自拟题目，写一篇文章。","why":"作答需要围绕题中判断立论，并从材料案例和现实经验中选择论据支撑分论点。","origin":"逐题标记","originalId":"s-b723abade67b1127"}],"stem":"“给定材料5”中提到“我们要用积极的态度对旧事物的价值进行最大挖掘，让它们重新焕发生机”，请你对此进行深\n入思考，参考给定材料，联系实际，自选角度，自拟题目，写一篇文章。（35分）\n要求：\n（1）观点明确，见解深刻；\n（2）参考“给定材料”，但不拘泥于“给定材料”；\n（3）思路清晰，语言流畅；\n（4）字数1000～1200字。","options":[],"answer":"","analysis":"挖掘旧物价值 焕发蓬勃生机\n  在现代人眼里，以“老物件”为代表的旧事物被认为是“落后”、“陈旧”的“破烂儿”，在当下的“生活革命”中被淘汰、\n遗忘，渐趋消亡。但是，在历史长河里，每一个老物件都曾有自己的时光坐标，记录了时代变迁，托举起社会发展\n进步的新支点。因此，我们要用积极的态度，历史的、发展的、辩证的眼光，最大化挖掘旧物的价值，并进行创新\n利用，让它们重新焕发生机。\n  要充分挖掘旧物中承载的技艺、情感和故事，重新认识其蕴含的审美和文化基因，并赋予其经济价值。虽然社\n会的飞速发展革新使得一些旧物的使用价值被淡化，但是这些历经岁月变迁、时代变革的“老物件”，依然蕴含有丰富\n的价值，值得我们深入挖掘。比如旧物所承载的指尖技艺，展现着古人的匠心独运和古朴之美；聆听旧物背后的岁\n月故事，引发情感共鸣，能育人于无痕；二手经济的兴起，使看似是“废旧垃圾”的旧物重新获得了生命，孕育出一个\n蓬勃的新产业……一件件承载着人们情感和记忆的旧物，在历史的沉淀中被赋予了更加多元化的价值。因此，我们\n必须打破思维禁锢、转变观念认知，结合当下的新时代需求更加深入地思考旧事物的价值，赋予其新的使命，与其\n对话、沟通，滋养精神，慰藉心灵。\n  要让旧事物重新展现价值，就必须要重视对旧物的保护和修复，这既需要专业的技巧，也要有情感的投入。一\n方面，旧物保护修复要专业化，做到“科学诊断、精准治疗”。旧物件往往具有一定的稀缺性，独一无二、不可再生。\n而不专业的修补带来的破坏有时比岁月流逝带来的自然损坏更加严重，甚至会造成不可逆的破坏。因此，从方案制\n定到专职人员，从辅助工具到修复技法……保护修复的各个流程环节都要保证科学、专业，才能真正赋能旧物新\n生。另一方面，修复师要认识到这项工作的重大意义，将自身感情融入到修复工作中。旧物保护修复工作精细、复\n杂，要有发自肺腑的喜爱和热情、甘愿坐冷板凳的毅力与耐心，方能做到精雕细琢、精益求精。\n  要让旧事物重现生机、长期存续，关键是要做好对公众的教育工作，推动其重新回归人们的生活。“活鱼须在水\n中看”，旧物必须融入民众生活，否则只会变成“束之高阁”的老古董，久而久之便会无人问津。对此，我们要创新转\n化、活化利用，让旧物重新走入寻常百姓中间。一方面要立足当代人的生活方式，对其进行功能性改造，使其更好\n更多地融入生活场景，成为日常生活的组成部分；另一方面要将政策保护与市场化运作相结合，把“指尖技艺”变\n成“指尖经济”。比如国家对非遗的保护扶持，激励了更多人才投身非遗传承发展，许多老手艺、老物件才从“活下\n来”到“火起来”。因此，旧物只要能扎根并服务人民，就一定能获得“产生新时间”的能力，重新活跃。\n   旧事物不仅仅是器物，更承载着历史文化、情感记忆，如同一座丰富的宝库，值得我们深入思考挖掘，让它重\n新焕发出蓬勃生命力。\n文章分析\n                   挖掘旧物价值 焕发蓬勃生机\n  【标题的优点：首先，标题中含有主题词，使文章主题更突出、清晰。其次，标题在形式上采用对称式结构，\n使标题更有亮点。】\n  （1）在现代人眼里，以“老物件”为代表的旧事物被认为是“落后”、“陈旧”的“破烂儿”，在当下的“生活革命”中被淘\n汰、遗忘，渐趋消亡。（2）但是，在历史长河里，每一个老物件都曾有自己的时光坐标，记录了时代变迁，托举起\n社会发展进步的新支点。（3）因此，我们要用积极的态度，历史的、发展的、辩证的眼光，最大化挖掘旧物的价\n值，并进行创新利用，让它们重新焕发生机。\n   【开头的优点：★内容方面。范文的开头是紧扣“旧物价值”这一主题展开的。（1）首先介绍了现代人眼中“旧\n物”是无价值的；（2）其次接着用转折的表述，阐释了老物件有其特有的价值；（3）最后指出了要用积极的态度，\n最大化挖掘旧物的价值，引出观点。★文字表达方面。使用了“但是”“因此”等连接词，使语言表达有逻辑性；长短句\n配合使用，使得语言表达有节奏感。】\n  要充分挖掘旧物中承载的技艺、情感和故事，重新认识其蕴含的审美和文化基因，并赋予其经济价值。（1）虽\n然社会的飞速发展革新使得一些旧物的使用价值被淡化，但是这些历经岁月变迁、时代变革的“老物件”，依然蕴含有\n丰富的价值，值得我们深入挖掘。比如旧物所承载的指尖技艺，展现着古人的匠心独运和古朴之美；聆听旧物背后\n的岁月故事，引发情感共鸣，能育人于无痕；二手经济的兴起，使看似是“废旧垃圾”的旧物重新获得了生命，孕育出\n一个蓬勃的新产业……一件件承载着人们情感和记忆的旧物，在历史的沉淀中被赋予了更加多元化的价值。因此，\n（2）我们必须打破思维禁锢、转变观念认知，结合当下的新时代需求更加深入地思考旧事物的价值，赋予其新的使\n命，与其对话、沟通，滋养精神，慰藉心灵。\n  【论述段1的优点：★观点句：范文的观点句是紧扣“旧物价值”这一文章主题提出的。形式上，它在段首处直接\n写出，位置突出，容易发现。内容上，关键词突出，内容要点明确，可以明显看出主要论述“要充分挖掘旧物中承载\n的技艺、情感和故事”。★论述内容：（1）先介绍了飞速发展的社会淡化了旧物的价值，但是它们还蕴含着不一样的\n审美；（2）然后总结性的指出了要转变思维观念，深入思考旧物的价值。注意：以上两个方面的内容都是紧扣“要充\n\n分挖掘旧物中承载的技艺、情感和故事，重新认识其蕴含的审美和文化基因，并赋予其经济价值”这个观点句进行分\n析论述的，论述的针对性强，内容层次丰富。在论述方法上主要采用了讲道理、举例子相结合的方式，论述充实深\n刻。】\n  要让旧事物重新展现价值，就必须要重视对旧物的保护和修复，这既需要专业的技巧，也要有情感的投入。\n（1）一方面，旧物保护修复要专业化，做到“科学诊断、精准治疗”。旧物件往往具有一定的稀缺性，独一无二、不\n可再生。而不专业的修补带来的破坏有时比岁月流逝带来的自然损坏更加严重，甚至会造成不可逆的破坏。因此，\n从方案制定到专职人员，从辅助工具到修复技法……保护修复的各个流程环节都要保证科学、专业，才能真正赋能\n旧物新生。（2）另一方面，修复师要认识到这项工作的重大意义，将自身感情融入到修复工作中。旧物保护修复工\n作精细、复杂，要有发自肺腑的喜爱和热情、甘愿坐冷板凳的毅力与耐心，方能做到精雕细琢、精益求精。\n  【论述段2的优点：★观点句：范文的观点句是紧扣“旧物价值”这一文章主题提出的。形式上，它在段首处直接\n写出，位置突出，容易发现。内容上，关键词突出，内容要点明确，可以明显看出主要论述“要重视对旧物的保护和\n修复”。★论述内容：（1）对旧物的保护修复要专业；（2）对旧物的保护修复要融入感情。注意：以上两个方面的\n内容都是紧扣“要让旧事物重新展现价值，就必须要重视对旧物的保护和修复，这既需要专业的技巧，也要有情感的\n投入”这个观点句进行分析论述的，论述的针对性强，内容层次丰富。在论述方法上主要采用了讲道理、举例子相结\n合的方式，论述充实深刻。】\n  要让旧事物重现生机、长期存续，关键是要做好对公众的教育工作，推动其重新回归人们的生活。“活鱼须在水\n中看”，（1）旧物必须融入民众生活，否则只会变成“束之高阁”的老古董，久而久之便会无人问津。对此，（2）我\n们要创新转化、活化利用，让旧物重新走入寻常百姓中间。一方面要立足当代人的生活方式，对其进行功能性改\n造，使其更好更多地融入生活场景，成为日常生活的组成部分；另一方面要将政策保护与市场化运作相结合，把“指\n尖技艺”变成“指尖经济”。比如国家对非遗的保护扶持，激励了更多人才投身非遗传承发展，许多老手艺、老物件才\n从“活下来”到“火起来”。因此，（3）旧物只要能扎根并服务人民，就一定能获得“产生新时间”的能力，重新活跃。\n   【论述段3的优点：★观点句：范文的观点句是紧扣“旧物价值”这一文章主题提出的。形式上，它在段首处直接\n写出，位置突出，容易发现。内容上，关键词突出，内容要点明确，可以明显看出主要论述“要让旧事物重现生机、\n长期存续”。★论述内容：（1）首先阐释了旧物融入民众生活的必然性；（2）其次具体阐述了如何创新转化、活化\n利用旧物；（3）最后总结性的指出只有让旧物扎根并服务人民，才能让其重现生机。注意：以上三个方面的内容都\n是紧扣“要让旧事物重现生机、长期存续，关键是要做好对公众的教育工作，推动其重新回归人们的生活”这个观点句\n进行分析论述的，论述的针对性强，内容层次丰富。在论述方法上主要采用了讲道理、举例子相结合的方式，论述\n充实深刻。】\n  【论述段之间的关系：★内在逻辑上：文章先论述“要充分挖掘旧物中承载的技艺、情感和故事”，再论述“要重\n视对旧物的保护和修复”，最后论述“要让旧事物重现生机、长期存续”，逻辑清晰严谨。】\n  旧事物不仅仅是器物，更承载着历史文化、情感记忆，如同一座丰富的宝库，值得我们深入思考挖掘，让它重\n新焕发出蓬勃生命力。\n  【结尾的优点：范文的结尾回扣了“旧物价值”这个主题，并且进行了展望，发出了号召。】","figs":[],"state":"已标记","notes":[],"domains":["文化"],"nature":"综合题","current":false},"国考 2024 行政执法 申论#5":{"paper":"国考 2024 行政执法 申论","n":5,"mod":"申论","src":["b9a9a500aad1608fddd0.pdf",4],"asrc":["b899d5c3aecda01e69ec.pdf",4],"m":["2b5f408c5bc7a0a1","f4bc77ded7297bfa","8716ee830c1d8b54","79740cef9272f9f5","db4340d3a5c1fe31"],"task":"结合材料5和实际，自拟题目写一篇1000～1200字的议论文，阐明行政执法中的“力”“理”“利”及其关系。","current_affairs":{"state":"否","event":null,"year":null,"basis":"作答依据是材料所给的执法案例和一般性执法要求。"},"links":[{"id":"k-f773092eb52962fa","label":"行政执法应依法履职并防止权力滥用","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"执法部门监管到位，执法力量不缺位","why":"参考文章以监管到位和依法用权界定执法的适当力度。","origin":"逐题标记"},{"id":"k-4848d111468ef4ae","label":"行政执法应以证据认定事实、依法作出决定并释法明理","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"M1","quote":"认定讲证据、裁量讲道理、决定讲法律","why":"材料以精准执法和向当事人讲清理由说明执法中“理”的要求。","origin":"逐题标记"},{"id":"k-8b474f6d84c52725","label":"行政执法应以维护公众权益为目标，通过全过程记录、信息公开和公众参与接受监督","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"M1","quote":"以‘老百姓看得见’的执法方式，促进全过程阳光执法，提高政府公信力。","why":"参考文章以执法公开和公众监督说明保障公共利益的具体途径。","origin":"逐题标记"},{"id":"s-4fdadcb77809c673","label":"阐释题给关键词并据其关系组织分论点","catalog_id":null,"type":null,"role":"直接考查","field":"answer","quote":"最后指出了如何正确处理行政执法工作中“力”“理”“利”的关系。","why":"需要先明确三个关键词在执法中的含义，再用分论点说明它们如何共同服务于公共利益。","origin":"逐题标记","originalId":"s-ac1ed570b80968f5"},{"id":"s-b8139af04b609dce","label":"用案例和道理论证分论点","catalog_id":null,"type":null,"role":"直接考查","field":"answer","quote":"在论述方法上主要采用了讲道理、举例子相结合的方式。","why":"需要选取与分论点相符的执法案例，并说明案例如何支撑判断。","origin":"逐题标记","originalId":"s-2730c04bc455ea33"}],"stem":"请结合“给定材料5”，围绕行政执法工作中的“力”“理”“利”进行深入思考，联系实际，自拟题目，写一篇文章。\n（35分）\n\n要求：\n（1）观点明确，见解深刻；\n（2）参考给定材料，但不拘泥于给定材料；\n（3）思路清晰，语言流畅；\n（4）字数1000～1200字。","options":[],"answer":"","analysis":"行政执法的力理利\n  法者，国之权衡也，时之准绳也。行政执法关乎社会公平正义，而现代执法理念则为执法工作指明了方向：正\n确行使“力”量，合法使用手段，确保执法的公正和权威；通过“理”性思考，做出科学合理决策，保证执法结果合规；\n最终以实现社会公众“利”益为目标，保护公民权益，提高执法的公信力和效能。只有力、理、利三者同时兼顾，行政\n执法工作才能更好地发挥作用，为社会稳定和公民安全提供更好保障。\n  行政执法需要有恰当的“力”度，这种力度既要求执法部门监管到位，执法力量不缺位，充分体现政府公信力，\n也要求执法人员不滥用权力，执法行为公正、有序，充分体现合法性。在行政执法工作中，合法性是权威性的基\n础，而权威性则能进一步增强合法性。近年来，我国推进依法行政工作取得了重大进展，但仍然存在某些地方和部\n门对法律法规的认识不足、执行不力的问题，个别行政干部在履行职责时存在滥用职权、任性执法等现象，降低了\n政府公信力。要解决这些问题，需要加强对执法人员的执法能力培训和职业道德建设，提升其法律素养和责任意\n识，也要建立健全监督机制，及时发现、纠正不当执法行为，保障行政执法工作公正合规。\n  行政执法要有充分的“理”由，在执法过程中，要贯彻“释法明理、法理相融”的执法理念，对执法对象讲清事\n理、法理、情理，充分答疑释惑，做到精准执法、柔性执法。孔子提出过“道之以政，齐之以刑，民免而无耻；道之\n以德，齐之以礼，有耻且格”，论证了执法工作要承担教育民众的功能。习近平总书记也强调“法律并不是冷冰冰的条\n文，背后有情有义”，说明执法要有温度。在行政执法工作中，执法人员一定要保持审慎态度，充分进行调查，确保\n事实证据确凿无疑，在与执法对象沟通过程中，也要多一丝善意和温暖，优先运用说服教育、示范指导等柔性方\n式，让当事人心服口服，在融洽的氛围中解决问题。\n  归根结底，行政执法最应聚焦的当属公众的“利”益。除却依靠适度的“力”和充分的“理”，还要提升公开透明程\n度和公众参与度，让政府接受人民的监督和评议。全面依法治国最广泛、最深厚的基础是人民，要把维护人民权\n益、增进人民福祉落实到全面依法治国各领域全过程。从执法过程配备专业执法记录设备，让执法全过程得到清晰\n记录，到各地海关纷纷推行“双随机、一公开”的监管模式，通过公开执法过程和结果，公众可以了解执法部门的行\n为，有助于维护公平公正的执法环境。公众参与则可以促使行政执法更符合社会舆论和民意要求，实现更好的行政\n决策和执法结果。只有行政执法在阳光下运行，公开透明，法治的红利才能惠及全体人民。\n  行政执法要加大力度、讲究适度、体现温度、增加透明度、最终提升群众满意度，让人民群众在每一个执法行\n为中都能看到风清气正、从每一项执法决定中都能感受到公平正义！\n文章分析：\n                      行政执法的力理利\n  【标题的优点：标题中含有主题词，使文章主题突出、清晰。】\n  （1）法者，国之权衡也，时之准绳也。行政执法关乎社会公平正义，（2）而现代执法理念则为执法工作指明\n了方向：正确行使“力”量，合法使用手段，确保执法的公正和权威；通过“理”性思考，做出科学合理决策，保证执法\n结果合规；最终以实现社会公众“利”益为目标，保护公民权益，提高执法的公信力和效能。（3）只有力、理、利三\n者同时兼顾，行政执法工作才能更好地发挥作用，为社会稳定和公民安全提供更好保障。\n  【开头的优点：★内容方面。范文的开头是紧扣题目给定的“行政执法工作”这一主题展开的。（1）首先简要分\n析了“行政执法”的重要性。（2）接着对行政执法工作中“力”“理”“利”的含义进行了阐释。（3）最后指出了如何正确处\n理行政执法工作中“力”“理”“利”的关系。★文字表达方面。使用了“只有”“才能”等连接词，增强了论述逻辑的严谨\n性。】\n  行政执法需要有恰当的“力”度。这种力度既要求执法部门监管到位，执法力量不缺位，充分体现政府公信力，\n也要求执法人员不滥用权力，执法行为公正、有序，充分体现合法性。（1）在行政执法工作中，合法性是权威性的\n基础，而权威性则能进一步增强合法性。（2）近年来，我国推进依法行政工作取得了重大进展，但仍然存在某些地\n方和部门对法律法规的认识不足、执行不力的问题，个别行政干部在履行职责时存在滥用职权、任性执法等现象，\n降低了政府公信力。（3）要解决这些问题，需要加强对执法人员的执法能力培训和职业道德建设，提升其法律素养\n和责任意识，也要建立健全监督机制，及时发现、纠正不当执法行为，保障行政执法工作公正合规。\n  【论述段1的优点：★观点句：范文的观点句是紧扣“行政执法工作”这一主题提出的。形式上，它在段首处直接\n写出，位置突出，容易发现。内容上，关键词突出，内容要点明确，可以明显看出主要论述“行政执法工作要\n有‘力’度”。★论述内容：（1）介绍了执法工作合法性与权威性的关系；（2）介绍了我国行政执法工作取得的成绩与\n存在的问题；（3）针对行政执法工作中存在的问题提出了解决措施。注意：以上三个方面的内容都是紧扣“行政执法\n需要有恰当的‘力’度，这种力度既要求执法部门监管到位，执法力量不缺位，充分体现政府公信力，也要求执法人员\n不滥用权力，执法行为公正、有序，充分体现合法性”这个观点句进行分析论述的，论述的针对性强，内容层次丰\n富。在论述方法上主要采用了讲道理、举例子相结合的方式。】\n  行政执法要有充分的“理”由，在执法过程中，要贯彻“释法明理、法理相融”的执法理念，对执法对象讲清事\n理、法理、情理，充分答疑释惑，做到精准执法、柔性执法。（1）孔子提出过“道之以政，齐之以刑，民免而无耻；\n道之以德，齐之以礼，有耻且格”，论证了执法工作要承担教育民众的功能。（2）习近平总书记也强调“法律并不是\n\n冷冰冰的条文，背后有情有义”，说明执法要有温度。（3）在行政执法工作中，执法人员一定要保持审慎态度，充分\n进行调查，确保事实证据确凿无疑，在与执法对象沟通过程中，也要多一丝善意和温暖，优先运用说服教育、示范\n指导等柔性方式，让当事人心服口服，在融洽的氛围中解决问题。\n  【论述段2的优点：★观点句：范文的观点句是紧扣“行政执法工作”这一主题提出的。形式上，它在段首处直接\n写出，位置突出，容易发现。内容上，关键词突出，内容要点明确，可以明显看出主要论述“行政执法要有‘理’由”。\n★论述内容：（1）介绍了行政执法工作要承担教育民众的功能；（2）介绍行政执法工作应当有温度；（3）分析了\n执法人员具体应当采取的措施。注意：以上三个方面的内容都是紧扣“行政执法要有充分的‘理’由，在执法过程中，要\n贯彻‘释法明理、法理相融’的执法理念，对执法对象讲清事理、法理、情理，充分答疑释惑，做到精准执法、柔性执\n法”这个观点句进行分析论述的，论述的针对性强，内容层次丰富。在论述方法上主要采用了讲道理、举例子相结合\n的方式。】\n  由以上可见，行政执法有力、有理，可以更好地维护公共利益。而民众作为利益相关方，维护自己利益的需求\n必然更为迫切。因此，在当下，有必要创新行政执法方式，让公众参与到行政执法工作中。\n  【过渡段的优点：本段既是对前面两个论述段的总结，也是对下一个论述段的预告，起到了承上启下的过渡作\n用，让文章在结构上衔接得十分自然流畅。】\n  归根结底，行政执法最应聚焦的当属公众的“利”益。除却依靠适度的“力”和充分的“理”，还要提升公开透明程\n度和公众参与度，让政府接受人民的监督和评议。（1）全面依法治国最广泛、最深厚的基础是人民，要把维护人民\n权益、增进人民福祉落实到全面依法治国各领域全过程。（2）从执法过程配备专业执法记录设备，让执法全过程得\n到清晰记录，到各地海关纷纷推行“双随机、一公开”的监管模式，通过公开执法过程和结果，公众可以了解执法部门\n的行为，有助于维护公平公正的执法环境。（3）公众参与则可以促使行政执法更符合社会舆论和民意要求，实现更\n好的行政决策和执法结果。只有行政执法在阳光下运行，公开透明，法治的红利才能惠及全体人民。\n  【论述段3的优点：★观点句：范文的观点句是紧扣“行政执法工作”这一主题提出的。形式上，它在段首处直接\n写出，位置突出，容易发现。内容上，关键词突出，内容要点明确，可以明显看出主要论述“创新行政执法方式，提\n升公众参与度”。★论述内容：（1）介绍了执法为民的原因；（2）介绍了提升执法公开透明度的具体措施；（3）\n介绍了公众参与行政执法的重要性。注意：以上三个方面的内容都是紧扣“行政执法最应聚焦的当属公众的‘利’益。除\n却依靠适度的‘力’和充分的‘理’，还要提升公开透明程度和公众参与度，让政府接受人民的监督和评议”这个观点句进\n行分析论述的，论述的针对性强，内容层次丰富。在论述方法上主要采用了讲道理、举例子相结合的方式。】\n   【论述段之间的关系：★内在逻辑上：文章先论述“行政执法工作要有‘力’度”，再论述“行政执法工作要\n有‘理’由”，最后论述“提升公开透明程度和公众参与度，让政府接受人民的监督和评议”，在语义上逐渐递进，逻辑清\n晰严谨。】\n  行政执法要加大力度、讲究适度、体现温度、增加透明度、最终提升群众满意度，让人民群众在每一个执法行\n为中都能看到风清气正、从每一项执法决定中都能感受到公平正义！\n  【结尾的优点：范文的结尾回扣了“行政执法工作”这个主题，并且进行了展望，发出了号召。】","figs":[],"state":"已标记","notes":[],"domains":["法律","公共管理"],"nature":"综合题","current":false}},"materialFiles":{"d8aed48987730819":"110aa277ecdd52252f8ebda0","83b1ed6111d1ae4e":"fa8f3d472f28604670b35b09","dd9e2108e0e953e8":"e962e9013bf4c2912216817b","d4e0e7e85f06007d":"b9ea366b4fb4a8d598cd42d7","01efb1670d7870db":"ca51e34160756e771a63e4fe","178887103fc17b90":"4afcd5cb05b711ad60108756","65cf3240786dbd61":"6af97eace1455e77091eff17","fb5ef365f00b5993":"772b9c03b42e8a6f9031ea6b","d2f9c6b742757876":"72e97cf575ec9838d2914f45","6644520b217e1626":"48526faa975a5120c75076ed","2b5f408c5bc7a0a1":"23b5e37a0844a2f5730fdeed","f4bc77ded7297bfa":"4c382e2c57fb9bed98d61519","8716ee830c1d8b54":"ffa5102dfb0c6faf44d7d152","79740cef9272f9f5":"33e0402491158a6605757260","db4340d3a5c1fe31":"b26e093ba5f638f903ecb49c"},"terms":{"k-8aa6c40ec20de676":{"id":"k-8aa6c40ec20de676","mode":"k","type":"观点与论证","title":"追寻长期价值","qs":[],"count":1},"k-4d3454f7f078b01c":{"id":"k-4d3454f7f078b01c","mode":"k","type":"观点与论证","title":"理性的认知框架","qs":[],"count":1},"k-d814f6a0f46ef3a6":{"id":"k-d814f6a0f46ef3a6","mode":"k","type":"观点与论证","title":"企业创造长期价值","qs":[],"count":1},"k-475b76e8b7a3951f":{"id":"k-475b76e8b7a3951f","mode":"k","type":"观点与论证","title":"政府立足长期利益","qs":[],"count":1},"k-4ac3bc37c7df3b81":{"id":"k-4ac3bc37c7df3b81","mode":"k","type":"观点与论证","title":"社会力量与长期发展","qs":[],"count":1},"s-4fdadcb77809c673":{"id":"s-4fdadcb77809c673","mode":"s","type":"文章写作","title":"围绕中心论点组织分论点","qs":[],"count":8},"s-b8139af04b609dce":{"id":"s-b8139af04b609dce","mode":"s","type":"文章写作","title":"展开分论点的论证","qs":[],"count":14},"k-b7c045465e9e618c":{"id":"k-b7c045465e9e618c","mode":"k","type":"观点与论证","title":"旧物的多重价值","qs":[],"count":1},"k-a2892e57edb4b096":{"id":"k-a2892e57edb4b096","mode":"k","type":"观点与论证","title":"旧物保护与修复","qs":[],"count":1},"k-e0770253109af00a":{"id":"k-e0770253109af00a","mode":"k","type":"观点与论证","title":"旧物融入日常生活","qs":[],"count":1},"k-f773092eb52962fa":{"id":"k-f773092eb52962fa","mode":"k","type":"观点与论证","title":"行政执法的力度","qs":[],"count":1},"k-4848d111468ef4ae":{"id":"k-4848d111468ef4ae","mode":"k","type":"观点与论证","title":"释法明理、法理相融","qs":[],"count":1},"k-8b474f6d84c52725":{"id":"k-8b474f6d84c52725","mode":"k","type":"观点与论证","title":"阳光执法与公众监督","qs":[],"count":1}},"questions":{}},"firstMaterials":[{"key":"d8aed48987730819","value":["材料5","材料5\n  某学者近期发表了一篇题为《追寻长期价值》的文章。文章指出，这几年，全球经济社会发展面临着更加复杂\n的变化和更多的不确定性。面对一只只“黑天鹅”，很多人可能会从应对危机中总结出一个道理：面对“未知的未知”，\n我们必须增加应对不确定性的韧性，增强适应持续变化的环境的能力。这就要求我们不惧短期挫折，抵御短期诱\n惑，心怀信念，坚持把时间和精力投入到能够产生长期价值的事上。\n  该学者认为，于个人而言，这是一种清醒，要求人们建立理性的认知框架，不受繁杂噪声的影响。于企业而\n言，这是一种格局，要求企业不断进化、不断创造价值。于政府而言，这是一种担当，必须立足长期利益，致力长\n远发展。于社会而言，这是一种热忱，无数力量汇聚到支撑人类长期发展的领域，形成一个个生生不息、持续发展\n的正向循环。",["ac29447768aa30db2247.pdf",4]],"label":"国考 2023 地市级 申论|材料5"},{"key":"83b1ed6111d1ae4e","value":["材料1","材料1\n  翻开A市地图，仿佛能看到林海苍翠、流水潺潺，一幅美丽的画卷徐徐展开，跃然眼前。今天，当清新的空气、\n清澈的溪流也能“卖”上大价钱时，GEP正成为A市缩小与省内其他地区发展差距的一个突破口。\n  2018年，习近平总书记在深入推动长江经济带发展座谈会上强调，要选择具备条件的地区开展生态产品价值实\n现机制试点。而A市，正是生态产品价值实现机制试点城市之一。\n  “所谓GEP，是指生态产品价值的总和，它反映了森林、湿地和农田等生态系统产生的直接、间接或潜在的经济\n效益。”A市生态环境局赵局长介绍，“我们制定了一套GEP核算方法，对生态产品价值进行评估、核算，并积极探索\n核算结果落地应用，助力我市加快推进生态产品价值实现。”\n  碧澜乡是A市一个山区乡镇。对这里的村民来说，以前开农家乐是可以想象得到的致富来源，但GEP核算告诉他\n们，还有另外的致富之路。碧澜乡的溪流不但拥有矿泉水般的水质，而且水流形态丰富，急流种类多样，是天然的\n水域救援训练场地。乡里利用这一优势，开发了水域救援培训项目。碧澜乡党委王书记说：“从原生态的水到致富的\n水，GEP核算起到了加速转化的作用。GEP核算报告让我们知道生态资源究竟好在哪儿，进而合理有序地转化为经\n济效益。”\n   不仅碧澜乡，对A市其他乡镇来说，这种发展思路都具有实际指导意义。云瀑乡党委李书记说，如果不是看到\nGEP核算报告，他实在不敢想，云瀑乡的峡谷、瀑布、云海，放在整个A市都颇有竞争力。云瀑乡已经和一家公司进\n行合作，在当地开发探险类项目和梯田观光项目。相应的，该公司向云瀑乡生态强村公司支付300万元，购买项目所\n在区域的生态产品，形成良性循环。\n  截至2021年底，A市所有乡镇均组建了生态强村公司，主攻生态产品价值转化，负责自然资源管理与开发、生态\n环境保护与修复等，成为公共生态产品的供给主体和市场化交易主体。金融市场也闻风而动，“GEP贷”等金融产品应\n运而生。\n  在蕊溪岸边，芳草镇党委马书记介绍，镇里新开发了“溪游记”旅游项目，将蕊溪流域丰富的生态资源串点成线，\n建成后有望成为拉动全镇经济的重要引擎。芳草镇虽然成立了生态强村公司，公司却没有实体抵押物，想要贷款融\n资并不容易。2022年3月，以芳草镇调节服务类和文化服务类两类生态产品的使用经营权作为质押担保，他们拿到了\n500万元的“GEP贷”，这不仅解决了旅游项目建设的资金需求，也激活了生态产品的金融属性。\n  常年奔波在A市的乡村，某大学经济学院黄教授深谙GEP核算的魅力。他表示，GEP核算报告就像人的体检报\n告，各地可以根据报告来强优势、补短板，推动生态优势转化为产业优势。这样的探索在A市已经展开。比如，一批\n电子仪器企业、医药公司等环境敏感型企业纷纷选择在A市落户。某医药公司董事长说：“生产高品质的医药容器对\n环境有着严格的要求，A市具有无可比拟的一流生态环境，这是我们选择这里的根本原因。”\n  位于A市景叶县的“天工之城”——未来科技岛，也正在尝试。山水之间，一批高新技术企业已逐绿而来。景叶县\n两山转化发展中心工作人员方女士介绍：“我们把生态产品价值作为生产要素参与合作企业的利润分配，实现经济创\n收。我们正在做的一件事，就是把‘生态绿谷’转化为‘数字绿谷’。”\n  日前，A市“两山银行”与明渚乡签下首笔湿地碳汇收储合约，以每吨58.83元的价格购入明渚乡湿地一万吨碳汇\n量。同时，“两山银行”又向该市农商银行等9家单位分别出售碳汇量，这也是A市将GEP核算应用到碳汇市场的首次\n尝试。\n  “党的二十大报告提出积极稳妥推进碳达峰碳中和。湿地碳汇交易就是利用湿地植物光合作用吸收二氧化碳释放\n氧气的过程，实现碳减排；再将所减排的碳量用于市场交易，实现碳中和。”赵局长表示，“这既可鼓励企业参与生态\n保护，也能激励企业推行低碳生产。碳汇交易的获益资金还可用于湿地绿化扩面、修复等工作，反哺湿地生态建\n设，进一步提升生态系统碳汇能力，可谓一举多得。”",["ac29447768aa30db2247.pdf",1]],"label":"国考 2023 地市级 申论|材料1"},{"key":"dd9e2108e0e953e8","value":["材料2","材料2\n  “随着我国创新型国家建设和知识产权战略实施的不断推进，政府知识产权工作的着力点，已从知识产权制度的\n构建转变成为推动市场主体对知识产权制度的有效运用。”知识产权领域一位资深专家表示，“在我国知识产权制度从\n建立到不断完善的过程中，这将是我国知识产权事业发展的新方向。”\n  “在市知识产权信息服务中心的助力下，‘川兴米粉’获得地理标志保护，带动了整个企业品牌乃至行业的发展。我\n们通过不断完善特色加工工艺、加强历史文化传承等，持续推动‘川兴米粉’高质量发展。”L市镇办企业川兴米粉有限\n公司冯经理说。\n\n  L市知识产权信息服务中心成立于2017年10月，主要职能是面向社会开展知识产权法律法规宣传、专利技术展示\n宣传和推介转化，提供专利情报与商标信息、专利信息传播与利用、知识产权司法鉴定与知识产权培训等一系列服\n务工作。2018年，L市知识产权信息服务中心派专项组进驻各乡镇。在中心指导下，“川兴米粉”正式成为国家地理标\n志产品。2022年，在L市知识产权信息服务中心的引导下，“川兴米粉”联盟标准及地方标准先后出台。统一的标准是\n提升产品质量的保证，一路走来，“川兴米粉”在标准化和规范化道路上渐行渐稳，走上了高质量发展的“快车道”。\n  三月江南，草莓上市。在L市各大中高端超市的水果货架上，随处可见“丰禾庄园”的精品草莓。“丰禾庄园”是一家\n集草莓育种、种植与销售于一体的创新型企业。该企业吴经理介绍，企业赢得市场青睐的秘诀之一在于，L市知识产\n权信息服务中心协助企业分析研判发展“痛点”，精准对接高端科研团队，为产品的提档升级注入了科技基因。\n  通过知识产权信息服务中心的对接，L市农业学院方教授团队与“丰禾庄园”就草莓生产等方面展开合作。2021年\n底，三方围绕草莓育苗基质配制、有机肥研发利用、知识产权信息服务等需求，共同签署了“丰禾庄园与L市农业学院\n合作框架协议”。很快，方教授带领团队帮助企业解决了草莓生产中的一个个关键问题。\n  传统的地栽草莓垄高一般在20-30厘米，工人必须弯下腰来采摘，费时费力。为了改变这一现状，在L市知识产\n权信息服务中心的协调下，企业尝试引进高垄种植技术，不仅让草莓采收轻松省力，而且还利用其采光好、透气性\n强的优点，有效促进了草莓增产。\n  香田蓝莓花开、浮山春茶开采……良好的生态环境，孕育出千姿百态的“伊山山珍”。以前，这些产品虽好，但其\n经营户处于小、散、弱的状态，销售渠道也不通畅。\n  乡村振兴，产业兴旺是基础。为此，L市知识产权信息服务中心为“伊山山珍”品牌商标注册量身定制工作方案，\n确定注册商标样式，进行品牌知识产权保护布局、品牌图文版权登记等。针对山珍品种繁多问题，知识产权信息服\n务中心安排信息员就相关产品类别在国家知识产权局商标数据库对48个类别进行近200次检索，整理出商品商标申请\n清单和服务商标申请清单，指导相关企业将60余种产品分期分批开展商标注册申请。\n  “没有自己的品牌，好山珍卖不出好价钱。今年我们取得了‘伊山山珍’的商标使用权，对于销售信心倍增。”伊山\n村一位种植大户说。\n  “多年来，村里人专注于山珍的培育，却忽略了知识产权的保护，时有冒牌货流入市场，损害了本地山珍的信\n誉。”伊山农村联合社郑社长感慨，“知识产权信息服务中心给我们做了商标法宣讲，对商标持有人进行培训，并指导\n我们制定了《“伊山山珍”商标标识使用管理办法》。现在我们得到商标的授权，消费者对我们的信任度高了，销量自\n然上去了。”\n  L市知识产权信息服务中心还联合多个部门合力推动“企业+地理标志商标+标准化+农户”模式，重点推广当地主\n导产业，成功打造了以蓝莓、竹荪、两茶一药等为重点的“伊山山珍”拳头产品，许多产品备受顾客青睐和市场欢迎。",["ac29447768aa30db2247.pdf",1]],"label":"国考 2023 地市级 申论|材料2"},{"key":"d4e0e7e85f06007d","value":["材料3","材料3\n  “光伏电站装到一半，村里突然来人告诉我不要装了，说是后面会有其他厂商统一安装，可是我已经装好的那部\n分怎么办？总不能拆掉吧？”\n   近日，S市的一些群众陆续向市能源局反映，在安装屋顶光伏电站过程中遇到了一些麻烦事。对此，市新能源办\n公室牵头组成调研组进行了深入的实地走访调查。\n   2021年9月，国家有关部门公布了整县（市、区）屋顶分布式光伏开发试点名单，强调各试点地区要严格落\n实“自愿不强制、试点不审批、到位不越位、竞争不垄断、工作不暂停”的工作要求，不断改善新能源开发建设营商环\n境，降低屋顶分布式光伏开发建设成本，减轻投资开发企业负担，相关部门要加强监管。其中，S市有10个县被列入\n试点名单。\n   “随着分布式光伏‘整县推进’步伐不断加快，屋顶光伏行业迎来跨越式发展，吸引了大型国企民企和众多中小企业\n前来角逐。”S市C县一光伏品牌代理商陈经理告诉调研组，“一个县的屋顶资源有限，僧多粥少，竞争自然非常激\n烈。”陈经理说，为此他特意扩大了业务人员规模，准备逐村逐户进行“地毯式”开拓。但是，就在他准备大展身手之\n际，却发现当地屋顶光伏的建设进度放缓了。\n   为何更多企业参与之后，反而“拖累”了屋顶光伏“整县推进”的步伐？调研组了解到，与这一现象同时出现的，是\n不少地方正在探索“一企包一县”的开发模式。\n   “所谓‘一企包一县’，就是地方政府将整个县的屋顶资源，都打包交给一家企业去做。”分布式光伏行业资深专家\n谭先生告诉调研组，“农户屋顶资源是建一户少一户，谁掌握了这些终端资源，谁就能在未来的市场竞争中拥有话语\n权。”\n   B县的一位光伏代理商汪经理也告诉调研组，自己已经半年没有新项目了。半年前，B县政府曾发布一则通知，\n暂缓全县范围内一切光伏项目。他说：“虽然文件也明确指出支持各类市场主体参与整县分布式光伏开发，企业可根\n据自身条件和优势，通过市场竞争方式参与整县规模化开发，但最终政府还是将整县资源打包交给了一家大型国\n企。”\n   B县政府相关部门工作人员告诉调研组，在建设初期，屋顶光伏领域一度处于鱼龙混杂的状态，一些不负责任的\n企业损害农户利益。地方政府在执行“整县推进”时，确实需要优先选择有实力的企业，先把市场的良性秩序建立起\n来。\n\n  调研组了解到，在光伏发电开发实施过程中，确实出现过村民受骗的情况。D县南坞村的村民老宋就向调研组讲\n述了自己被骗的经历。“前年夏天，有人来我家说可以建屋顶光伏，通过阳光发电，不仅家里以后不用交电费了，多\n余的电还可以卖钱。”老宋对调研组说，一开始，对方说自家不用花一分钱，只用提供自家屋顶就行，结果等到要安\n装时才发现，自己要垫付一部分费用，而且安装过程中还会收取很多杂七杂八的费用。如果拒绝安装，就需要交一\n部分违约金，最终他只好选择继续安装。“问题是，东西才装了不到一年就坏了，再找对方维修时，人都找不到了，\n白白亏了不少钱。”正是市场中有人“浑水摸鱼”，地方政府才不得不格外谨慎，在选择“整县推进”的合作伙伴时，更倾\n向于大型企业。\n  调研组在调查中还发现，在S市其他没有实行“一企包一县”的区域，当地农户在自家屋顶安装一个光伏电站，每\n块太阳能光伏板的大致收益是一年50元左右，而在S市已实行“一企包一县”的区域，收益则普遍降低至40元左右。\n  “一般一个农户家的屋顶光伏电站会用到60多块板子，如果实行‘一企包一县’，一年下来老百姓就会减少不少收\n入。”谭先生告诉调研组，由于光伏电站收益周期较长，对农户而言，多年累积下来，就会损失一笔不小的收入。因\n此农户会质疑，别家给的租金多，有什么理由不让他们装别家的？\n  那么，为什么会存在差价？谭先生透露说：“这可能是因为目前一些‘整县包干’的大型企业，对市场有些‘水土不\n服’。要知道，大型企业一般都是主攻集中式光伏的，对分布式光伏市场并不熟悉，其竞争优势得不到体现。因此，\n有些企业也考虑过把这项工作转包给在地方上有经验的中小公司去做。可一旦转包，在部分地区就可能存在政策、\n流程、质量等诸多不确定性风险。”\n  E县的一名光伏代理商吴经理对调研组说：“去年我们公司主要做的是三县党政机关和学校的屋顶，不过县政府\n并没有专门对接这项业务的人，屋顶的产权开发协调需要企业单独去跑。今年开始安装户用，但到底是一户一户单\n独备案，还是打包备案，目前这一块还没明确。”\n  “如今市场环境变了，原有格局被打破，新的模式尚未成熟，这个过程中，必然会暴露出各种各样的问题。”谭先\n生认为，“在这个时候能够及时发现问题、暴露矛盾也不是坏事。如果能积极探索出一种政府有为、企业有利、百姓\n受益的解决路径，就真正达到了试点的目的。”",["ac29447768aa30db2247.pdf",2]],"label":"国考 2023 地市级 申论|材料3"},{"key":"01efb1670d7870db","value":["材料4","材料4\n  M市是一座有名的制造业城市，汇聚着成千上万的中小微企业。然而，这些企业因自身资金有限，风险降临时，\n可能无力抵御；机会来临时，也往往难以把握。2020年3月，M市F银行召开了普惠金融战略启动大会，宣布要加大\n对中小微企业的服务力度。\n  风馨达环保科技公司是M市一家以专业化、精细化、特色化、新颖化为特征的“小巨人”企业。2020年底，公司决\n定贷款新建一条废旧线路板及其边角料规模化回收生产线。需求一提出，F银行工作人员便向其推荐了“小企快贷”。\n针对小微企业金融需求“短、频、急”的特点，“小企快贷”业务通过系统整合，运用大数据分析审批申请。相比以往的\n线下调查等流程，企业无需再人工提交资料，只需授权F银行查阅相应数据即可。最终，这家企业顺利通过F银行审\n批，很快获得约200万元的贷款。\n  对此，F银行的张经理感受很深：“以前一线业务都需要客户给流水，然后我们去考察这个流水和客户规模、经\n营是否匹配，时间很长、流程复杂，而且一些小微企业是没办法提供流水的。电子化之后就很方便，后台直接根据\n他们的水电费、税款等各项开支做出计算和判断。门槛低了很多，大部分小微企业都可以去申请。”他谈到，这两年\n普惠金融业务在云技术的支持下，改变了不少。\n  同业务量一起上涨的，还有员工们的成就感。F银行内部转发的一名客户经理对普惠金融战略的心声，曾引发广\n泛共鸣：“对比动辄千万元的大业务，这一笔笔微不足道的‘小业务’或许就是一家家企业和背后许多家庭的救命钱。”\n  2021年底，张经理又跟进了几笔餐饮店的贷款。新冠肺炎疫情期间，M市多地实行了小区封闭管理，不少餐饮\n店也只能“放长假”。“那期间，这些餐饮店几乎没有什么生意，他们也没有做外卖，资金链就很容易出问题，可能三\n个月都撑不住。”\n  为此，F银行联合M市美食协会、M市餐饮协会创新推出了“美食贷”。通过企业授权，统一从行业协会获取相关\n数据，以作为对应的贷款依据，让这些餐饮店能够更快拿到资金。\n  这些餐饮店正是靠着“美食贷”挺了过来。再后来疫情趋于平缓，餐饮店的生意也陆续恢复。张经理感叹，相比大\n企业，小企业数量更多。若这些“小草”能在浇灌中成长，就能为新时代的发展带来更多的生机。\n  小林是F银行派驻到苗种村的第一书记，她用两年的时间，为村里打开了脱贫致富的出路——建设特色乡村旅游\n区。然而民宿和餐馆的前期投入不小，而且在短期内无法回本。刚开始，这一点吓退了很多村民。面对这个难题，\n她想到可以借助创新信贷政策为村里筹集建设资金。这样，村民们就不用承担过高的资金压力。\n  在此基础上，考虑到乡村的交通困境、资金往来的不便，小林在F银行的帮助下，将小型移动银行——“惠农\n达”开在了村中的小卖部里，村民得以在家门口办理金融业务，行动不便的老人直接就可以在村里领取养老金、办理\n社保了。实现金融服务覆盖的苗种村，业务办理呈现出新活力。\n  “我们始终坚持‘金融向善’的理念，让全体社会成员公平享有金融服务的机会。我们将服务公众需求作为业务目\n标，更有温度地回应人民对美好生活的向往。”F银行黄行长说道，“为此我们更加广泛地进行业务拓展，自身发展也\n更具有韧性。”\n\n  “叮咚”，伴随着清脆的手机提示音，老杨的工资到账了。老杨是一名外来务工人员，每天辛勤地忙碌着，最开心\n的时候就是每月发工资的日子。而为此提供帮助的，正是F银行的“务工达”。\n  F银行的“务工达”运用互联网技术，通过联接整合政府部门、总包、劳务公司、外来务工人员和用工管理平台等\n多方资源，打通产业链各环节，利用供应链融资驱动，为外来务工人员提供量身定制的专属服务。老杨说：“现在直\n接由银行把钱打到我们卡上，准时足额，这样发工资的方式真好！”除此之外，F银行还为外来务工人员开通手机银\n行等便利服务，提供个人快贷服务，以备不时之需。\n  对于F银行而言，普惠金融不仅是一种业务，更应是一个平台。“企心助农”就是F银行带领爱心小微企业主一起做\n公益的平台，除了定向捐助，还会提供技术支持和工作岗位，从源头上解决农户返贫问题。不少小微企业主都是从\n农村出来的，多年打拼成功后，回过头来看到同村、同宗的人需要帮助，他们的感触往往都很深。自己被雨淋过，\n所以也想为别人撑把伞，或许这便是那些小微企业主愿意参与进来的原因之一。这些年来，F银行帮助了不少企业成\n长壮大。如今，它也在不断创造机会，让更多企业家参与进来，为实现共同富裕出一份力。",["ac29447768aa30db2247.pdf",3]],"label":"国考 2023 地市级 申论|材料4"}],"node":{"id":"s-4fdadcb77809c673","mode":"s","title":"围绕中心论点组织分论点","type":"文章写作","domain":"社会治理","reading":"","intro":"","priority":100,"aliases":["从材料观点提炼中心论点并按主体组织分论点","把材料中的主题判断转化为有实例支撑的分论点","阐释题给关键词并据其关系组织分论点","围绕中心论点提炼并列分论点","从多则材料中提炼共同机制并构建分论点","围绕题干关键词从材料案例提炼分论点","为给定主题提炼分论点并按意义与对策组织论证"],"qs":["国考 2023 地市级 申论#5","国考 2024 副省级 申论#5","国考 2024 行政执法 申论#5","国考 2025 副省级 申论#5","国考 2025 地市级 申论#5","国考 2025 行政执法 申论#5","江苏 2024 A类 申论#4","江苏 2025 A类 申论#4"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"subject":"申论","publishedSets":[{"name":"围绕中心论点组织分论点","ids":["国考 2023 地市级 申论#5","国考 2024 副省级 申论#5","国考 2024 行政执法 申论#5","国考 2025 副省级 申论#5","国考 2025 地市级 申论#5","国考 2025 行政执法 申论#5","江苏 2024 A类 申论#4","江苏 2025 A类 申论#4"],"units":[["国考 2023 地市级 申论#5"],["国考 2024 副省级 申论#5"],["国考 2024 行政执法 申论#5"],["国考 2025 副省级 申论#5"],["国考 2025 地市级 申论#5"],["国考 2025 行政执法 申论#5"],["江苏 2024 A类 申论#4"],["江苏 2025 A类 申论#4"]]}]}};
